verifier.cmd:
F=$(mktemp -d) && printf "import test from 'node:test';
import net from 'node:net';
test('opens a socket', () => { const s = net.connect(9, '192.0.2.1'); s.on('error', () => {}); s.destroy(); });
" > "$F/sock.test.mjs" && node --test "$F/sock.test.mjs" >/dev/null 2>&1 && ! NODE_OPTIONS="--import=$PWD/test/helpers/no-network.mjs" node --test "$F/sock.test.mjs" >/dev/null 2>&1 && S=$(mktemp -d) && H=$(mktemp -d) && N=$(dirname $(command -v node)) && for b in gh ssh ssh-keygen launchctl systemctl loginctl schtasks; do printf '#!/bin/sh
echo "$0 $*" >> %s/log
exit 127
' "$S" > "$S/$b" && chmod +x "$S/$b"; done && env -i PATH="$S:/usr/bin:/bin:$N" HOME="$H" MEMEV_NO_SERVICE=1 npm_config_update_notifier=false NODE_OPTIONS="--import=$PWD/test/helpers/no-network.mjs" npm test && test ! -s "$S/log"
